38	func newAttachCmd() *cobra.Command {
39		var (
40			force     bool
41			agentFlag string
42		)
43		cmd := &cobra.Command{
44			Use:   "attach <session-id>",
45			Short: "Attach an existing agent session",
46			Long: `Attach an existing agent session that wasn't captured by hooks.
47	
48	This creates a checkpoint from the session's transcript and links it to the
49	last commit. Use this when hooks failed to fire or weren't installed when
50	the session started, or to attach a research session.
51	
52	If the last commit already has a checkpoint, the session is added to it.
53	Otherwise a new checkpoint is created.
54	
55	Works with any registered agent, including external agents enabled via
56	external_agents in settings. Run 'entire configure' to see the full list.`,
57			RunE: func(cmd *cobra.Command, args []string) error {
58				if len(args) != 1 {
59					return cmd.Help()
60				}
61				if checkDisabledGuard(cmd.Context(), cmd.OutOrStdout()) {
62					return nil
63				}
64				// Discover external agents so --agent <external-name> is recognized
65				// and so auto-detection can find transcripts from external agents.
66				external.DiscoverAndRegister(cmd.Context())
67				agentName := types.AgentName(agentFlag)
68				return runAttach(cmd.Context(), cmd.OutOrStdout(), args[0], agentName, force)
69			},
70		}
71		cmd.Flags().BoolVarP(&force, "force", "f", false, "Skip confirmation and amend the last commit with the checkpoint trailer")
72		cmd.Flags().StringVarP(&agentFlag, "agent", "a", string(agent.DefaultAgentName), "Agent that created the session (see 'entire configure' for registered agents, including external)")
73		return cmd
74	}
75	
76	func runAttach(ctx context.Context, w io.Writer, sessionID string, agentName types.AgentName, force bool) error {
77		// Initialize structured logger so logging.Warn/Info write to .entire/logs/ not stderr.
78		if err := logging.Init(ctx, sessionID); err != nil {
79			// Init failed — logging will use stderr fallback, non-fatal.
80			_ = err
81		}
82		defer logging.Close()
83	
84		logCtx := logging.WithComponent(ctx, "attach")
85	
86		// Open repository once — shared across all operations.
87		repo, err := openRepository(ctx)
88		if err != nil {
89			return err
90		}
91	
92		existingState, err := validateAttachPreconditions(ctx, repo, sessionID)
93		if err != nil {
94			return err
95		}
96	
97		headCommit, err := getHeadCommit(repo)
98		if err != nil {
99			return err
100		}
101	
102		// If session already has a checkpoint, just offer to link it.
103		if existingState != nil && !existingState.LastCheckpointID.IsEmpty() {
104			cpID := existingState.LastCheckpointID.String()
105			fmt.Fprintf(w, "Session %s already has checkpoint %s\n", sessionID, cpID)
106			if err := promptAmendCommit(logCtx, w, headCommit, cpID, force); err != nil {
107				logging.Warn(logCtx, "failed to amend commit", "error", err)
108				fmt.Fprintf(w, "\nCopy to your commit message to attach:\n\n  Entire-Checkpoint: %s\n", cpID)
109			}
110			return nil
111		}
112	
113		// Resolve agent and transcript path.
114		ag, transcriptPath, err := resolveAgentAndTranscript(logCtx, w, sessionID, agentName, existingState)
115		if err != nil {
116			return err
117		}
118	
119		transcriptData, err := ag.ReadTranscript(transcriptPath)
120		if err != nil {
121			return fmt.Errorf("failed to read transcript: %w", err)
122		}
123	
124		// Normalize Gemini transcripts for storage.
125		storedTranscript := transcriptData
126		if ag.Type() == agent.AgentTypeGemini {
127			if normalized, normErr := geminicli.NormalizeTranscript(transcriptData); normErr == nil {
128				storedTranscript = normalized
129			} else {
130				logging.Warn(logCtx, "failed to normalize Gemini transcript, storing raw", "error", normErr)
131			}
132		}
133	
134		meta := extractTranscriptMetadata(transcriptData)
135	
136		// Determine checkpoint ID: reuse from HEAD if one exists, otherwise generate new.
137		checkpointID, isExistingCheckpoint := resolveCheckpointID(headCommit)
138	
139		// Refresh the metadata branch if HEAD already references a checkpoint.
140		// Returns a possibly-freshly-opened repo handle; see refreshForExistingCheckpoint.
141		repo = refreshForExistingCheckpoint(ctx, logCtx, repo, isExistingCheckpoint)
142	
143		// Write directly to entire/checkpoints/v1.
144		store := cpkg.NewGitStore(repo)
145		if err := verifyCheckpointLocallyAvailable(ctx, store, checkpointID, isExistingCheckpoint); err != nil {
146			return err
147		}
148	
149		author, err := GetGitAuthor(ctx)
150		if err != nil {
151			return fmt.Errorf("failed to get git author: %w", err)
152		}
153	
154		var prompts []string
155		if meta.FirstPrompt != "" {
156			prompts = []string{meta.FirstPrompt}
157		}
158	
159		tokenUsage := agent.CalculateTokenUsage(logCtx, ag, transcriptData, 0, "")
160	
161		_, redactSpan := perf.Start(ctx, "redact_transcript")
162		redactedTranscript, redactErr := redact.JSONLBytes(storedTranscript)
163		redactSpan.End()
164		if redactErr != nil {
165			return fmt.Errorf("failed to redact transcript: %w", redactErr)
166		}
167	
168		writeOpts := cpkg.WriteCommittedOptions{
169			CheckpointID: checkpointID,
170			SessionID:    sessionID,
171			Strategy:     strategy.StrategyNameManualCommit,
172			Transcript:   redactedTranscript,
173			Prompts:      prompts,
174			AuthorName:   author.Name,
175			AuthorEmail:  author.Email,
176			Agent:        ag.Type(),
177			Model:        meta.Model,
178			TokenUsage:   tokenUsage,
179		}
180	
181		if compacted := compactTranscriptForStartLine(logCtx, redactedTranscript.Bytes(), cpkg.CommittedMetadata{
182			CheckpointID: checkpointID,
183			Agent:        ag.Type(),
184		}, 0); compacted != nil {
185			writeOpts.CompactTranscript = compacted
186		}
187	
188		v2 := settings.CheckpointsVersion(logCtx) == 2
189		if !v2 {
190			if err := store.WriteCommitted(ctx, writeOpts); err != nil {
191				return fmt.Errorf("failed to write checkpoint: %w", err)
192			}
193		}
194		// IsCheckpointsV2Enabled is true whenever v2 writes are enabled, including
195		// both v2-only mode (checkpoints_version == 2) and dual-write mode. Only
196		// v2-only mode propagates the error.
197		if settings.IsCheckpointsV2Enabled(logCtx) {
198			if err := writeAttachCheckpointV2(logCtx, repo, writeOpts); err != nil {
199				if v2 {
200					return fmt.Errorf("failed to write checkpoint to v2: %w", err)
201				}
202				logging.Warn(logCtx, "attach v2 dual-write failed", "error", err)
203			}
204		}
205	
206		// Create or update session state.
207		if err := saveAttachSessionState(logCtx, existingState, sessionID, ag.Type(), transcriptPath, checkpointID, meta, tokenUsage); err != nil {
208			logging.Warn(logCtx, "failed to save session state", "error", err)
209		}
210	
211		fmt.Fprintf(w, "Attached session %s\n", sessionID)
212		if isExistingCheckpoint {
213			fmt.Fprintf(w, "  Added to existing checkpoint %s\n", checkpointID)
214			return nil
215		}
216	
217		fmt.Fprintf(w, "  Created checkpoint %s\n", checkpointID)
218		cpIDStr := checkpointID.String()
219		if err := promptAmendCommit(logCtx, w, headCommit, cpIDStr, force); err != nil {
220			logging.Warn(logCtx, "failed to amend commit", "error", err)
221			fmt.Fprintf(w, "\nCopy to your commit message to attach:\n\n  Entire-Checkpoint: %s\n", cpIDStr)
222		}
223	
224		return nil
225	}
