255	// refreshForExistingCheckpoint refreshes the entire/checkpoints/v1 branch
256	// before reading or writing when HEAD already references a checkpoint.
257	// This mirrors `entire resume`'s metadata fetch fallback chain so attach
258	// doesn't operate on a stale local orphan branch after a normal `git pull`.
259	// Returns a freshly-opened repo handle so go-git sees any newly fetched
260	// packfiles; on fetch failure, logs a warning and returns the original repo.
261	func refreshForExistingCheckpoint(ctx, logCtx context.Context, repo *git.Repository, isExistingCheckpoint bool) *git.Repository {
262		if !isExistingCheckpoint {
263			return repo
264		}
265		_, freshRepo, fetchErr := getMetadataTree(ctx)
266		if fetchErr != nil {
267			logging.Warn(logCtx, "failed to refresh metadata branch before attach; proceeding with local state",
268				slog.String("error", fetchErr.Error()))
269			return repo
270		}
271		return freshRepo
272	}
