274	// verifyCheckpointLocallyAvailable refuses the attach when HEAD references
275	// an Entire-Checkpoint that is still missing from the local
276	// entire/checkpoints/v1 branch after refresh. Without this guard, attach
277	// would create a fresh checkpoint under the same ID and overwrite the
278	// original session data on push.
279	func verifyCheckpointLocallyAvailable(ctx context.Context, store *cpkg.GitStore, checkpointID id.CheckpointID, isExistingCheckpoint bool) error {
280		if !isExistingCheckpoint {
281			return nil
282		}
283		summary, readErr := store.ReadCommitted(ctx, checkpointID)
284		if readErr != nil {
285			return fmt.Errorf("failed to read checkpoint %s: %w", checkpointID, readErr)
286		}
287		if summary != nil {
288			return nil
289		}
290		const fetchCmd = "git fetch origin entire/checkpoints/v1:entire/checkpoints/v1"
291		return fmt.Errorf(
292			"checkpoint %s referenced by HEAD is missing from the local entire/checkpoints/v1 branch (the remote fetch didn't bring it in either). Creating a fresh checkpoint here would overwrite the original session data on push. Run:\n\n    %s\n\nthen re-run attach. If the colleague who made this commit hasn't pushed their checkpoint metadata yet, ask them to do so first",
293			checkpointID.String(), fetchCmd,
294		)
295	}
