297	// resolveCheckpointID returns the checkpoint ID to use for the attach.
298	// If HEAD already has an Entire-Checkpoint trailer, reuses that ID (the session
299	// gets added as an additional session in the existing checkpoint).
300	// Otherwise generates a new ID.
301	func resolveCheckpointID(headCommit *object.Commit) (id.CheckpointID, bool) {
302		existing := trailers.ParseAllCheckpoints(headCommit.Message)
303		if len(existing) > 0 {
304			return existing[len(existing)-1], true
305		}
306	
307		cpID, err := id.Generate()
308		if err != nil {
309			// Generation only fails if crypto/rand fails — extremely unlikely.
310			// Fall back to empty which will cause WriteCommitted to fail with a clear error.
311			return id.EmptyCheckpointID, false
312		}
313		return cpID, false
314	}
