382	// resolveAgentAndTranscript resolves the agent and transcript path.
383	// For existing sessions, resolves the agent from session state's AgentType.
384	// For new sessions, uses the --agent flag with auto-detection fallback.
385	func resolveAgentAndTranscript(ctx context.Context, w io.Writer, sessionID string, agentName types.AgentName, existingState *session.State) (agent.Agent, string, error) {
386		ag, err := resolveAgent(existingState, agentName)
387		if err != nil {
388			return nil, "", err
389		}
390	
391		transcriptPath, err := resolveAndValidateTranscript(ctx, sessionID, ag)
392		if err != nil {
393			// Auto-detect: try all other agents.
394			detectedAg, detectedPath, detectErr := detectAgentByTranscript(ctx, sessionID, agentName)
395			if detectErr != nil {
396				return nil, "", fmt.Errorf("%w (also tried auto-detecting other agents: %w)", err, detectErr)
397			}
398			ag = detectedAg
399			transcriptPath = detectedPath
400			logging.Info(ctx, "auto-detected agent from transcript", "agent", ag.Name())
401			fmt.Fprintf(w, "Auto-detected agent: %s\n", ag.Name())
402		}
403	
404		return ag, transcriptPath, nil
405	}
