407	// resolveAgent resolves the agent to use. For existing sessions with an AgentType,
408	// uses agent.GetByAgentType. Otherwise falls back to the --agent flag.
409	func resolveAgent(existingState *session.State, agentName types.AgentName) (agent.Agent, error) {
410		if existingState != nil && existingState.AgentType != "" {
411			ag, err := agent.GetByAgentType(existingState.AgentType)
412			if err == nil {
413				return ag, nil
414			}
415			// Fall through to flag-based resolution.
416		}
417		ag, err := agent.Get(agentName)
418		if err != nil {
419			return nil, fmt.Errorf("agent %q not available: %w", agentName, err)
420		}
421		return ag, nil
422	}
