424	// resolveAndValidateTranscript finds the transcript file for a session, searching alternative
425	// project directories if needed.
426	func resolveAndValidateTranscript(ctx context.Context, sessionID string, ag agent.Agent) (string, error) {
427		transcriptPath, err := resolveTranscriptPath(ctx, sessionID, ag)
428		if err != nil {
429			return "", fmt.Errorf("failed to resolve transcript path: %w", err)
430		}
431		// Only call PrepareTranscript when the file already exists — it flushes
432		// in-progress writes, but can't conjure a file that was never started.
433		// This avoids agents like Cursor polling for 3s on non-existent files
434		// during auto-detection.
435		if _, statErr := os.Stat(transcriptPath); statErr == nil {
436			if preparer, ok := agent.AsTranscriptPreparer(ag); ok {
437				if prepErr := preparer.PrepareTranscript(ctx, transcriptPath); prepErr != nil {
438					logging.Debug(ctx, "PrepareTranscript failed (best-effort)", "error", prepErr)
439				}
440			}
441			return transcriptPath, nil
442		}
443		found, searchErr := searchTranscriptInProjectDirs(sessionID, ag)
444		if searchErr == nil {
445			logging.Info(ctx, "found transcript in alternative project directory", "path", found)
446			return found, nil
447		}
448		logging.Debug(ctx, "fallback transcript search failed", "error", searchErr)
449		return "", fmt.Errorf("transcript not found for agent %q with session %s; is the session ID correct?", ag.Name(), sessionID)
450	}
