452	// detectAgentByTranscript tries all registered agents (except skip) to find one whose
453	// transcript resolution succeeds for the given session ID.
454	func detectAgentByTranscript(ctx context.Context, sessionID string, skip types.AgentName) (agent.Agent, string, error) {
455		for _, name := range agent.List() {
456			if name == skip {
457				continue
458			}
459			ag, err := agent.Get(name)
460			if err != nil {
461				continue
462			}
463			path, resolveErr := resolveAndValidateTranscript(ctx, sessionID, ag)
464			if resolveErr != nil {
465				logging.Debug(ctx, "auto-detect: agent did not match", "agent", string(name), "error", resolveErr)
466				continue
467			}
468			return ag, path, nil
469		}
470		return nil, "", errors.New("transcript not found for any registered agent")
471	}
