292	// writeStandardCheckpointEntries writes session files to numbered subdirectories and
293	// maintains a CheckpointSummary at the root level with aggregated statistics.
294	//
295	// Structure:
296	//
297	//	basePath/
298	//	├── metadata.json         # CheckpointSummary (aggregated stats)
299	//	├── 1/                    # First session
300	//	│   ├── metadata.json     # CommittedMetadata (session-specific, includes initial_attribution)
301	//	│   ├── full.jsonl
302	//	│   ├── prompt.txt
303	//	│   └── content_hash.txt
304	//	├── 2/                    # Second session
305	//	└── ...
306	func (s *GitStore) writeStandardCheckpointEntries(ctx context.Context, opts WriteCommittedOptions, basePath string, entries map[string]object.TreeEntry) error {
307		// Read existing summary to get current session count
308		var existingSummary *CheckpointSummary
309		metadataPath := basePath + paths.MetadataFileName
310		if entry, exists := entries[metadataPath]; exists {
311			existing, err := s.readSummaryFromBlob(entry.Hash)
312			if err == nil {
313				existingSummary = existing
314			}
315		}
316	
317		// Determine session index: reuse existing slot if session ID matches, otherwise append
318		sessionIndex := s.findSessionIndex(ctx, basePath, existingSummary, entries, opts.SessionID)
319	
320		// Capture any pre-existing session-0 metadata before writeSessionToSubdirectory
321		// clears that subtree. This is a diagnostic tripwire for a production report
322		// where session 0 was silently replaced by a different session's data.
323		var existingSessionZeroMeta *CommittedMetadata
324		if sessionIndex == 0 {
325			if entry, exists := entries[fmt.Sprintf("%s0/%s", basePath, paths.MetadataFileName)]; exists {
326				if existingMeta, readErr := s.readMetadataFromBlob(entry.Hash); readErr == nil {
327					existingSessionZeroMeta = existingMeta
328				}
329			}
330		}
331	
332		// Write session files to numbered subdirectory
333		sessionPath := fmt.Sprintf("%s%d/", basePath, sessionIndex)
334		sessionFilePaths, err := s.writeSessionToSubdirectory(ctx, opts, sessionPath, entries)
335		if err != nil {
336			return err
337		}
338	
339		// Copy additional metadata files from directory if specified (to session subdirectory)
340		if opts.MetadataDir != "" {
341			if err := s.copyMetadataDir(opts.MetadataDir, sessionPath, entries); err != nil {
342				return fmt.Errorf("failed to copy metadata directory: %w", err)
343			}
344		}
345	
346		// Build the sessions array
347		var sessions []SessionFilePaths
348		if existingSummary != nil {
349			sessions = make([]SessionFilePaths, max(len(existingSummary.Sessions), sessionIndex+1))
350			copy(sessions, existingSummary.Sessions)
351		} else {
352			sessions = make([]SessionFilePaths, 1)
353		}
354		sessions[sessionIndex] = sessionFilePaths
355	
356		// Tripwire: if we're writing session 0 and there was already session-0
357		// metadata for a DIFFERENT session ID, emit a loud warning so we have a
358		// log trace instead of only the overwrite symptom.
359		if existingSessionZeroMeta != nil && existingSessionZeroMeta.SessionID != opts.SessionID {
360			logging.Warn(ctx, "checkpoint write overwrites session 0 with a different sessionID — potential overwrite regression",
361				slog.String("checkpoint_id", opts.CheckpointID.String()),
362				slog.String("existing_session_id", existingSessionZeroMeta.SessionID),
363				slog.String("write_session_id", opts.SessionID),
364				slog.Bool("existing_summary_nil", existingSummary == nil))
365		}
366	
367		// Update root metadata.json with CheckpointSummary
368		return s.writeCheckpointSummary(opts, basePath, entries, sessions)
369	}
