567	// findSessionIndex returns the index of an existing session with the given ID,
568	// or the next available index if not found. This prevents duplicate session entries.
569	func (s *GitStore) findSessionIndex(ctx context.Context, basePath string, existingSummary *CheckpointSummary, entries map[string]object.TreeEntry, sessionID string) int {
570		if existingSummary == nil {
571			return 0
572		}
573		for i := range len(existingSummary.Sessions) {
574			path := fmt.Sprintf("%s%d/%s", basePath, i, paths.MetadataFileName)
575			if entry, exists := entries[path]; exists {
576				meta, err := s.readMetadataFromBlob(entry.Hash)
577				if err != nil {
578					logging.Warn(ctx, "failed to read session metadata during dedup check",
579						slog.Int("session_index", i),
580						slog.String("session_id", sessionID),
581						slog.String("error", err.Error()),
582					)
583					continue
584				}
585				if meta.SessionID == sessionID {
586					return i
587				}
588			}
589		}
590		return len(existingSummary.Sessions)
591	}
