593	// reaggregateFromEntries reads all session metadata from the entries map and
594	// reaggregates CheckpointsCount, FilesTouched, and TokenUsage.
595	func (s *GitStore) reaggregateFromEntries(basePath string, sessionCount int, entries map[string]object.TreeEntry) (int, []string, *agent.TokenUsage, error) {
596		var totalCount int
597		var allFiles []string
598		var totalTokens *agent.TokenUsage
599	
600		for i := range sessionCount {
601			path := fmt.Sprintf("%s%d/%s", basePath, i, paths.MetadataFileName)
602			entry, exists := entries[path]
603			if !exists {
604				return 0, nil, nil, fmt.Errorf("session %d metadata not found at %s", i, path)
605			}
606			meta, err := s.readMetadataFromBlob(entry.Hash)
607			if err != nil {
608				return 0, nil, nil, fmt.Errorf("failed to read session %d metadata: %w", i, err)
609			}
610			totalCount += meta.CheckpointsCount
611			allFiles = mergeFilesTouched(allFiles, meta.FilesTouched)
612			totalTokens = aggregateTokenUsage(totalTokens, meta.TokenUsage)
613		}
614	
615		return totalCount, allFiles, totalTokens, nil
616	}
