71	{"type":"user","message":{"content":[{"type":"tool_result","tool_use_id":"tu_1","content":"wrote file"}]},"uuid":"uuid-3"}
72	{"type":"assistant","message":{"role":"assistant","content":[{"type":"text","text":"Done! I created hello.txt."}]},"uuid":"uuid-4"}
73	`)
74	
75		var out bytes.Buffer
76		err := runAttach(context.Background(), &out, sessionID, agent.AgentNameClaudeCode, true)
77		if err != nil {
78			t.Fatalf("runAttach failed: %v", err)
79		}
80	
81		// Verify session state was created
82		store, err := session.NewStateStore(context.Background())
83		if err != nil {
84			t.Fatal(err)
85		}
86		state, err := store.Load(context.Background(), sessionID)
87		if err != nil {
88			t.Fatal(err)
89		}
90		if state == nil {
91			t.Fatal("expected session state to be created")
92			return
93		}
94		if state.SessionID != sessionID {
95			t.Errorf("session ID = %q, want %q", state.SessionID, sessionID)
96		}
97		if state.LastCheckpointID.IsEmpty() {
98			t.Error("expected LastCheckpointID to be set after attach")
99		}
100	
101		// Verify output message
102		output := out.String()
103		if !strings.Contains(output, "Attached session") {
104			t.Errorf("expected 'Attached session' in output, got: %s", output)
105		}
106		if !strings.Contains(output, "Created checkpoint") {
107			t.Errorf("expected 'Created checkpoint' in output, got: %s", output)
108		}
